def _reset_overlay_state_for_overlay_launch(state_path: Path, client_type: str, logger: logging.Logger) -> None:
    previous_snapshot = _load_overlay_state_snapshot(state_path, client_type)
    snapshot = _empty_overlay_state_snapshot(client_type)
    _preserve_overlay_cached_self_profile(previous_snapshot, snapshot)
    snapshot["updated_at"] = datetime.now().isoformat(timespec="seconds")
    _write_overlay_state_snapshot(state_path, snapshot)
    logger.info("overlay state reset at launch: %s", state_path)


def _preserve_overlay_cached_self_profile(source_snapshot: dict[str, object], target_snapshot: dict[str, object]) -> None:
    source_player = source_snapshot.get("self_player")
    if not isinstance(source_player, dict):
        return
    target_player = target_snapshot.setdefault("self_player", {})
    for field_name in ("user_id", "nickname", "title", "title_id", "owned_title_ids", "fashions", "fashion_ids"):
        value = source_player.get(field_name)
        if value is not None:
            target_player[field_name] = value

