class StateStore:
    @contextmanager
    def batch(self):
        with self._lock:
            self._batch_depth += 1
        try:
            yield
        finally:
            should_dump = False
            with self._lock:
                self._batch_depth -= 1
                if self._batch_depth == 0 and self._batch_dirty:
                    self._batch_dirty = False
                    should_dump = True
            if should_dump:
                self.dump()

def _should_preserve_confirmed_skill_pps(previous_skill_ids: list[int], current: PetSummary, incoming: PetSummary) -> bool:
    current_source = str(current.skill_pp_source or "").strip().lower()
    incoming_source = str(incoming.skill_pp_source or "").strip().lower()
    if current_source not in CURRENT_BATTLE_SKILL_PP_SOURCES:
        return False
    if incoming_source in CURRENT_BATTLE_SKILL_PP_SOURCES:
        return False
    incoming_skill_ids = list(incoming.skill_ids)
    if previous_skill_ids and incoming_skill_ids and previous_skill_ids != incoming_skill_ids:
        return False
    return True

class ProfileService:
    def observe_send_packet(self, packet: PacketData) -> None:
        if packet.cmd_id != 41080 or len(packet.body) < 4:
            return
        forever_id = self._read_u32(packet.body, 0)
        self._pending_self_forever_41080.append(forever_id if is_peak_forever_id(forever_id) else None)
        if is_peak_forever_id(forever_id):
            self._logger.info("peak forever request observed: forever=%s", forever_id)

    def _handle_self_forever_value_41080(self, packet: PacketData) -> None:
        if len(packet.body) < 4 or not self._pending_self_forever_41080:
            return
        forever_id = self._pending_self_forever_41080.popleft()
        if forever_id is None:
            return
        value = self._read_u32(packet.body, 0)
        mode = peak_mode_for_forever_id(forever_id)
        payload = build_peak_mode_payload(mode, self._peak_forever_values_by_mode.setdefault(mode, {}))
        if payload:
            self._set_peak_mode_stats("self", mode, payload, replace_mode=mode not in self._peak_forever_initialized_modes)

def _build_overlay_view_model(snapshot: dict[str, object] | None, names: NameRepository | None = None, listen_mode: str | None = None, external_notice_text: str | None = None, pet_counters: PetCounterRepository | None = None, premium_features_enabled: bool = True) -> dict[str, object]:
    data = snapshot if isinstance(snapshot, dict) else {}
    self_player = data.get("self_player") if isinstance(data.get("self_player"), dict) else {}
    enemy_player = data.get("enemy_player") if isinstance(data.get("enemy_player"), dict) else {}
    phase = _detect_overlay_phase(data, self_player, enemy_player)
    battle_active = phase in {"bp", "battle", "transition"}

    return {
        "phase": phase,
        "battle_active": battle_active,
        "capture_status": _build_capture_status_model(data),
        "idle_account": _build_idle_account_model(self_player, names),
        "self_team": _build_self_team_model(self_player, names, battle_active),
        "enemy_focus": _build_enemy_focus_model(enemy_player, self_player, names, battle_active, pet_counters, phase=phase, premium_features_enabled=premium_features_enabled),
        "enemy_roster": _build_enemy_roster_model(enemy_player, names, battle_active, pre_battle_phase=phase == "bp", premium_features_enabled=premium_features_enabled),
        "enemy_unrevealed": _build_enemy_unrevealed_model(data, enemy_player, names, visible=phase in {"battle", "transition"}),
    }

class ResourceStore:
    def _row_by_id(self, item_id: int, *, cache_key: str, bundle_name: str, data_key: str, id_key: str, remote_kind: str, normalizer: callable) -> dict[str, Any] | None:
        if item_id <= 0:
            return None
        rows = self._cached_parsed(cache_key, lambda: _load_row_map(self.bundle(bundle_name).get(data_key), id_key))
        cached = rows.get(item_id)
        refresh_cached = remote_kind == "skill" and isinstance(cached, dict) and _remote_skill_row_needs_refresh(cached)
        if isinstance(cached, dict) and not refresh_cached:
            return cached

        payload = self._fetch_remote_row(remote_kind, item_id)
        if not isinstance(payload, dict):
            return cached if isinstance(cached, dict) else None
        row = normalizer(payload, item_id)
        if not isinstance(row, dict):
            return cached if isinstance(cached, dict) else None

        rows[item_id] = row
        self._merge_bundle_row(bundle_name, data_key, item_id, row)
        return row

def _write_bundle_file(self, bundle_name: str, payload: dict[str, Any]) -> None:
    path = self.bundle_path(bundle_name)
    temp_name: str | None = None
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False, dir=str(path.parent), prefix=f"{path.name}.", suffix=".tmp") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
            handle.write("\n")
            temp_name = handle.name
        Path(temp_name).replace(path)
    except Exception:
        if temp_name is not None:
            Path(temp_name).unlink(missing_ok=True)

def update_snapshot(self, snapshot: Mapping[str, object] | None) -> dict[str, object]:
    context = build_strategy_context(snapshot, self._names)
    session = build_strategy_session_context(snapshot, self._names)
    if context is None:
        with self._lock:
            self._clear_runtime_locked()
        return {"visible": False, "status": "idle", "title": "", "detail": ""}
    if session is None:
        return {"visible": True, "status": "loading", "title": "策略计算中", "detail": "正在等待本局阵容"}

    session_hash = strategy_session_hash(session)
    context_hash = strategy_context_hash(context)
    self._ensure_session_request(session, session_hash)

    with self._lock:
        policy = dict(self._session_policy) if self._session_hash == session_hash and isinstance(self._session_policy, dict) else None
    if policy is None:
        return {"visible": True, "status": "loading", "title": "策略计算中", "detail": "正在准备本局策略"}

    result = evaluate_strategy_policy(policy, context, execution_state={"cursors": dict(self._execution_cursors)})
    payload = {"schema_version": 1, "context_hash": context_hash, "session_hash": session_hash, "result": result}
    with self._lock:
        self._last_payload = payload
        self._remember_decision_locked(context, context_hash, session_hash, result)
    return _payload_to_strategy_model(payload)
